<script setup lang="ts">
import type { Programme } from '../../../../packages/contracts/src/programme';
import {programmeBoundary,storyAnchor,type StoryAnchor} from '../../../../packages/contracts/src/programme-navigation';
const {data,error}=await useFetch<{data:Programme[]}>('/api/v1/programmes');
const ready=computed(()=>(data.value?.data||[]).filter(p=>p.kind==='broadcast'));
const player=useProgrammeAudio(),route=useRoute();
const mode=ref<'solo'|'duo'>(ready.value.find(p=>p.programmeId===route.query.programme)?.variant==='duo'?'duo':'solo');
const requested=computed(()=>typeof route.query.programme==='string'?ready.value.find(p=>p.programmeId===route.query.programme):undefined);
const explicit=ref(true),story=ref(typeof route.query.story==='string'?route.query.story:requested.value?.articleSlugs[0]||ready.value[0]?.articleSlugs[0]||'');
const treatment=ref(requested.value?.mediaTreatment||(!route.query.programme&&ready.value.some(p=>p.articleSlugs.includes(story.value)&&p.mediaTreatment==='narration_over_visual'&&p.videoRendition)?'narration_over_visual':'legacy'));
const preferred=ref<{anchorCount?:number;mediaTreatment?:string}|null>(null);
const selected=computed(()=>{if(explicit.value&&route.query.programme&&!requested.value)return undefined;const p=ready.value.find(p=>p.variant===mode.value&&p.articleSlugs.includes(story.value)&&(p.mediaTreatment||'legacy')===treatment.value);if(p&&explicit.value&&typeof route.query.story==='string'&&typeof route.query.version==='string'&&programmeBoundary(p,{slug:route.query.story,versionId:route.query.version})===null)return undefined;return p;});
const storyOptions=computed(()=>[...new Set(ready.value.flatMap(p=>p.articleSlugs))].map(value=>({value,label:ready.value.flatMap(p=>p.chapters).find(c=>c.articleSlug===value)?.title||value})));
const treatmentOptions=computed(()=>[{value:'narration_over_visual',label:'Narration over visuals'},{value:'clip_then_comment',label:'Clip, then commentary'},{value:'legacy',label:'Original mixed edit'}].map(o=>({...o,disabled:!ready.value.some(p=>p.articleSlugs.includes(story.value)&&p.variant===mode.value&&(p.mediaTreatment||'legacy')===o.value&&p.videoRendition)})));
const alternatives=computed(()=>ready.value.filter(p=>p.articleSlugs.includes(story.value)&&p.videoRendition));
const videoPlayer=ref<{play:()=>Promise<void>;pause:()=>void;seek:(seconds:number,autoplay?:boolean)=>void}|null>(null);
const requestedPosition=typeof route.query.position==='string'?Number(route.query.position):0;
const resumeMatches=!!selected.value?.videoRendition&&route.query.rendition===selected.value.videoRendition.renditionKey;
const mappedStart=selected.value&&typeof route.query.story==='string'&&typeof route.query.version==='string'?programmeBoundary(selected.value,{slug:route.query.story,versionId:route.query.version,blockId:typeof route.query.block==='string'?route.query.block:undefined}):0;
const initialPosition=resumeMatches&&Number.isFinite(requestedPosition)&&requestedPosition>=0?Math.min(requestedPosition,selected.value!.videoRendition!.durationMs/1000):mappedStart||0;
const position=ref(initialPosition),startAt=ref(initialPosition),audioMode=ref(false),notice=ref(route.query.rendition&&!resumeMatches?'The saved video version is no longer available. The current edition is paused at its beginning.':resumeMatches?'Saved video position restored. Press Play when ready.':'');
const current=computed(()=>selected.value?.segments.find(s=>position.value*1000>=s.startMs&&position.value*1000<s.endMs));
const anchor=computed<StoryAnchor|undefined>(previous=>{const next=selected.value?storyAnchor(selected.value,position.value):undefined;return previous&&next&&previous.slug===next.slug&&previous.versionId===next.versionId&&previous.blockId===next.blockId?previous:next;});let previous:Programme|undefined;
function changeMode(){const anchor=previous?storyAnchor(previous,position.value):undefined;videoPlayer.value?.pause();player.pause();explicit.value=false;startAt.value=selected.value&&anchor?programmeBoundary(selected.value,anchor)||0:0;position.value=startAt.value;if(audioMode.value&&selected.value)player.setProgramme(selected.value,startAt.value);previous=selected.value;notice.value='Selection changed and paused at the corresponding section or story boundary. Press Play to confirm this edit. Your saved preference is unchanged.';}
function alternative(p:Programme){mode.value=p.variant==='duo'?'duo':'solo';treatment.value=p.mediaTreatment||'legacy';changeMode();notice.value='Temporary alternative selected and paused. Your saved preference is unchanged.';}
function listen(seconds=position.value){if(!selected.value)return;videoPlayer.value?.pause();player.clearVideo();audioMode.value=true;player.setProgramme(selected.value,seconds);player.audioOnly.value=true;void player.play();notice.value='Audio-only playback uses the same prepared soundtrack and can continue across reader pages.';}
function watchVideo(){player.pause();startAt.value=player.programme.value?.programmeId===selected.value?.programmeId?player.position.value:position.value;position.value=startAt.value;audioMode.value=false;notice.value='Prepared video selected and paused. Press Play when ready.';}
function seek(seconds:number){position.value=seconds;if(audioMode.value&&selected.value){player.setProgramme(selected.value,seconds);player.audioOnly.value=true;void player.play();}else videoPlayer.value?.seek(seconds,true);}
watch(player.position,value=>{if(audioMode.value)position.value=value;});
watch(()=>JSON.stringify([route.query.programme,route.query.story,route.query.version,route.query.block,route.query.rendition,route.query.position]),()=>{videoPlayer.value?.pause();audioMode.value=false;explicit.value=true;story.value=typeof route.query.story==='string'?route.query.story:requested.value?.articleSlugs[0]||ready.value[0]?.articleSlugs[0]||'';mode.value=requested.value?requested.value.variant==='duo'?'duo':'solo':preferred.value?.anchorCount===2?'duo':'solo';treatment.value=requested.value?.mediaTreatment||(requested.value?'legacy':preferred.value?.mediaTreatment||'narration_over_visual');const p=selected.value;const same=p?.videoRendition?.renditionKey===route.query.rendition;const seconds=Number(route.query.position);startAt.value=same&&Number.isFinite(seconds)&&seconds>=0?Math.min(seconds,p!.durationMs/1000):p&&typeof route.query.version==='string'?programmeBoundary(p,{slug:story.value,versionId:route.query.version,blockId:typeof route.query.block==='string'?route.query.block:undefined})||0:0;position.value=startAt.value;previous=p;notice.value=route.query.rendition&&!same?'The saved video version is no longer available. The current edition is paused.':'';});
onMounted(async()=>{previous=selected.value;try{const response=await $fetch<{data:{anchorCount?:number;playbackSpeed?:number;mediaTreatment?:string}}>('/api/v1/me/preferences');preferred.value=response.data;if(!route.query.programme&&explicit.value&&!player.videoState.value?.playing&&!audioMode.value){mode.value=response.data.anchorCount===2?'duo':'solo';if(response.data.mediaTreatment)treatment.value=response.data.mediaTreatment;if(selected.value&&typeof route.query.story==='string'&&typeof route.query.version==='string'){startAt.value=programmeBoundary(selected.value,{slug:route.query.story,versionId:route.query.version,blockId:typeof route.query.block==='string'?route.query.block:undefined})||0;position.value=startAt.value;}}previous=selected.value;if(response.data.playbackSpeed)player.setRate(response.data.playbackSpeed);}catch{/* Anonymous viewing remains available. */}});
useHead({title:'Newsroom — The Aggregator'});
</script>
<template>
  <main id="main" class="shell programme-page newsroom-page"><header class="programme-heading"><p class="eyebrow">The prepared edition · Original animated broadcast</p><h1>Newsroom</h1><p class="deck">The stories, their evidence, and the limits of what we know. Presented by Ada and Eli in an original animated studio.</p></header>
    <div v-if="ready.length" class="audio-options"><ControlSelect label="Story" v-model="story" :options="storyOptions" @change="changeMode"/><ControlSelect label="Media treatment" v-model="treatment" :options="treatmentOptions" @change="changeMode"/></div><p v-if="preferred" class="metadata">Saved preference: {{ preferred.anchorCount===2?'two anchors':'one anchor' }} · {{ preferred.mediaTreatment==='clip_then_comment'?'clip, then commentary':'narration over visuals' }}. Current selection: {{ mode==='duo'?'two anchors':'one anchor' }} · {{ treatmentOptions.find(o=>o.value===treatment)?.label }}. <NuxtLink to="/preferences">Edit saved preferences</NuxtLink></p><p v-if="error||!ready.length" class="media-unavailable">No ready Newsroom programme is available. The reader and its complete sources remain available.</p>
    <section v-else-if="!selected" role="status"><p>This broadcast is not prepared for the requested story version or preferred combination.</p><ControlButton v-for="p in alternatives" :key="p.programmeId" :label="`Use temporary alternative: ${p.title}`" @click="alternative(p)"/><NuxtLink to="/">Read the newspaper</NuxtLink></section><template v-else-if="selected"><div class="newsroom-edition"><div><p class="eyebrow">{{ selected.variant==='duo'?'Ada & Eli · Two anchors':'Ada · One anchor' }}</p><h2>{{ selected.title }}</h2></div><ControlSelect label="Presenter format" v-model="mode" :options="[{value:'solo',label:'One anchor · Ada'},{value:'duo',label:'Two anchors · Ada & Eli'}]" @change="changeMode"/></div>
      <p v-if="notice" role="status" class="listening-note">{{ notice }}</p>
      <BroadcastVideoPlayer v-if="selected.videoRendition&&!audioMode" :key="selected.videoRendition.renditionKey" ref="videoPlayer" :programme="selected" :start-at="startAt" @position="position=$event" @listen="listen"/>
      <section v-else class="newsroom-audio-alternative" aria-label="Audio and transcript alternative"><h2>{{ audioMode?'Audio edition':'The video edition is not available' }}</h2><p>{{ audioMode?'Listen without camera movement. The complete transcript and original source links follow below.':'This programme has a prepared soundtrack and transcript. No substitute animation is presented as a completed video.' }}</p><ControlButton v-if="!audioMode" label="Listen instead" variant="primary" @click="listen()"/><ProgrammeTransport v-if="audioMode"/></section>
      <div class="audio-actions newsroom-secondary"><ControlButton v-if="!audioMode" label="Listen instead" @click="listen()"/><ControlButton v-else-if="selected.videoRendition" label="Return to video" @click="watchVideo"/><a href="#transcript-title">Transcript &amp; complete sources</a></div>
      <p class="metadata">Prepared fictional reporting · Synthetic voices · Original animated presenters, not photorealistic people. This video includes camera movement; choose Listen instead for an audio and transcript alternative. Opening this page never starts playback.</p>
      <StoryFormats v-if="anchor" :slug="anchor.slug" :version-id="anchor.versionId" :block-id="anchor.blockId" /><ProgrammeTranscript :programme="selected" :video-mode="!!selected.videoRendition&&!audioMode" :active-segment-id="current?.id" @seek="seek"/>
    </template>
  </main>
</template>
<style scoped>
.newsroom-page{max-width:1120px}.newsroom-edition{display:flex;justify-content:space-between;align-items:end;gap:2rem;padding-top:1.2rem;border-top:1px solid var(--line,#bcb6aa)}.newsroom-edition h2{font-size:clamp(1.35rem,2.2vw,2rem);margin:.4rem 0 0}.newsroom-edition label{display:grid;gap:.45rem;flex-shrink:0;font-size:.8rem}.newsroom-edition select{padding:.65rem;background:transparent;color:inherit;border:1px solid var(--line,#aaa)}.newsroom-secondary{margin-block:1rem;align-items:center}.newsroom-audio-alternative{margin-block:1.5rem;padding:1.5rem;border-block:1px solid var(--line,#aaa)}@media(max-width:600px){.newsroom-edition{display:block}.newsroom-edition label{margin-top:1.2rem}.newsroom-audio-alternative{padding:1rem 0}}
</style>








